module pt_mgmt(input wire rst_n,por_n,input wire[2:0]por_path,input wire sclk,cs_n,mosi,output wire miso,miso_oe,
 input wire[15:0]status,output wire enable,mode8,output wire[15:0]rf_trim,wire_trim,clock_trim,
 output wire memory_write,output wire[4:0]memory_index,output wire[39:0]memory_wdata,
 input wire[39:0]capture_data,input wire capture_done,output wire playback_enable,capture_enable,
 output wire memory_loop,output wire[4:0]memory_last,
 input wire fault,input wire[5:0]island_pgood,input wire[31:0]obs_status,input wire[15:0]wire_status,
 output wire[609:0]analog_cfg,output wire[219:0]debug_cfg,
