 output wire commit_toggle,config_error,
 input wire[0:0]pattern_locked,
 input wire[0:0]pattern_lost_lock,
 input wire[15:0]pattern_errors_gray,
 input wire[0:0]fca_locked,
 input wire[0:0]fca_lost,
 input wire[13:0]fca_diff,
 input wire[15:0]fca_count,
 input wire[0:0]fcb_locked,
 input wire[0:0]fcb_lost,
 input wire[13:0]fcb_diff,
 input wire[15:0]fcb_count,
 input wire[9:0]mon_cause,
 input wire[0:0]mon_cause_clk,
 input wire[0:0]mon_ready,
 input wire[0:0]mon_dead,
 input wire[0:0]mon_ref_alive,
 input wire[0:0]mon_in_alive,
 input wire[0:0]mon_fault,
 input wire[9:0]mon_qualified,
 input wire[2:0]wtx_state,
 input wire[0:0]wtx_seq_fault,
 input wire[0:0]wtx_ring_ready,
 input wire[2:0]wrx_state,
 input wire[7:0]wrx_flags,
